/**
 * The `archived_at` columns along a subject's lineage — the subject itself,
 * then its issue, then its project — combined into one condition.
 */
type LineageCondition = (archivedAt: readonly SQLiteColumn[]) => SQL;

/** Subject, issue and project are all live. */
const allLive: LineageCondition = (archivedAt) =>
  and(...compact(...archivedAt.map((column) => livePredicate(column, {}))))!;

