function subjectLineageMatches(condition: LineageCondition): SQL {
  const db = getDb();
  const one = { one: sql`1` };

  const projectRow = db
    .select(one)
    .from(projects)
    .where(
      and(
        eq(projects.orgId, searchIndex.orgId),
