async function isIssueSearchable(orgId: OrgId, issue: Issue): Promise<boolean> {
  return isLive(issue) && (await isProjectSearchable(orgId, issue.projectId));
}

/**
 * Makes the index reflect one issue: upserted while it is searchable, and
 * otherwise dropped together with its comments.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (!(await isIssueSearchable(orgId, issue))) {
    await searchRepo.deleteIssueDocuments(orgId, issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
}

/** Makes the index reflect one comment: upserted only while searchable. */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const issue = isLive(comment)
    ? await issueRepo.findIssueById(orgId, comment.issueId)
    : null;

  if (issue === null || !(await isIssueSearchable(orgId, issue))) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

/**
 * Makes the index reflect one project's own document: upserted while the
 * project is live, and otherwise dropped along with everything beneath it.
 */
export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (!isLive(project)) {
    await searchRepo.deleteProjectDocuments(orgId, project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/** Re-reads an issue and brings its document in line with the rule. */
async function reindexIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue) await indexIssue(orgId, issue);
  else await searchRepo.deleteIssueDocuments(orgId, issueId);
}

/** Re-reads a comment and brings its document in line with the rule. */
async function reindexComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment) await indexComment(orgId, comment);
  else await removeFromIndex(orgId, "comment", commentId);
}

/** Re-reads a project and brings its own document in line with the rule. */
async function reindexProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) await indexProject(orgId, project);
  else await searchRepo.deleteProjectDocuments(orgId, projectId);
}

/**
 * Re-indexes a project together with its live issues and their live
 * comments — what a restore brings back. Issues archived with the project or
 * before it stay out, and so do their comments.
 */
async function reindexProjectContent(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project || !isLive(project)) {
    await searchRepo.deleteProjectDocuments(orgId, projectId);
    return;
  }

  await indexProject(orgId, project);

  const liveIssues = eachPageItem((cursor) =>
    issueRepo.listIssues({ orgId, projectId, limit: REINDEX_PAGE_SIZE, cursor }),
  );
  for await (const issue of liveIssues) {
    await indexIssue(orgId, issue);

    const liveComments = eachPageItem((cursor) =>
      commentRepo.listComments({
        orgId,
        issueId: issue.id,
        includeArchived: false,
        limit: REINDEX_PAGE_SIZE,
        cursor,
      }),
    );
    for await (const comment of liveComments) {
      await indexComment(orgId, comment);
    }
  }
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded — and every write goes through the index
 * writers above, so nothing under an archived issue or project is indexed.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await reindexIssue(payload.orgId, payload.issueId);
    }),
    subscribe("issue.updated", async (payload) => {
      await reindexIssue(payload.orgId, payload.issueId);
    }),
    subscribe("issue.archived", async (payload) => {
      await searchRepo.deleteIssueDocuments(payload.orgId, payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      await reindexComment(payload.orgId, payload.commentId);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      await reindexProject(payload.orgId, payload.projectId);
    }),
    subscribe("project.archived", async (payload) => {
      await searchRepo.deleteProjectDocuments(payload.orgId, payload.projectId);
    }),
    subscribe("project.restored", async (payload) => {
      await reindexProjectContent(payload.orgId, payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      switch (payload.subjectKind) {
        case "issue":
          return reindexIssue(payload.orgId, payload.subjectId as IssueId);
        case "comment":
          return reindexComment(payload.orgId, payload.subjectId as CommentId);
        case "project":
          return reindexProject(payload.orgId, payload.subjectId as ProjectId);
      }
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

