start=s.index('/**\n * Walks one tenant')
new='''/**
 * Walks one tenant's projects, issues and comments and re-upserts every
 * searchable document. Scoped to a single org on purpose: a full-fleet
 * reindex is a sequence of these, so one slow tenant cannot stall the rest.
 *
 * The rebuild leaves exactly what the searchability rule allows: documents
 * the rule no longer allows (archived or deleted rows, content under an
 * archived issue or project, duplicates) are pruned first, then every live
 * project, its live issues and their live comments are indexed — page by
 * page, so a large tenant is covered in full. Archived issues are not
 * brought back by a project restore, so they stay out here as well.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    const pruned = await searchRepo.pruneSearchDocuments(orgId);
    if (pruned > 0) {
      logger.info("pruned unsearchable documents", { orgId, pruned });
    }

    const liveProjects = eachPageItem((cursor) =>
      projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
    );

    for await (const project of liveProjects) {
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

      const liveIssues = eachPageItem((cursor) =>
        issueRepo.listIssues({
          orgId,
          projectId: project.id,
          limit: PAGE_SIZE,
          cursor,
        }),
      );

      for await (const issue of liveIssues) {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }

        const liveComments = eachPageItem((cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: false,
            limit: PAGE_SIZE,
            cursor,
          }),
        );

        for await (const comment of liveComments) {
          try {
            await indexComment(orgId, comment);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("failed to index comment", {
              commentId: comment.id,
              reason: error instanceof Error ? error.message : String(error),
            });
          }
        }
      }
    }
  });
}
