import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { getDb } from "@/server/db";
import { createTenant, issueInput, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void; let detach: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); detach = searchService.registerSearchListeners(); });
afterAll(() => { detach(); cleanup(); });

async function hits(t: any, q: string, kinds: any = ["issue", "comment", "project"]) {
  const r = await searchService.search(t.actors.member, { orgId: t.org.id, q, kinds, limit: 25, cursor: null });
  expect(r.items.length).toBe(Math.min(r.total, 25));
  return r.total;
}
const comment = (t: any, issueId: any, body: string) => commentService.createComment(t.actors.member, { orgId: t.org.id, issueId, body, parentId: null, mentionedUserIds: [] });

describe("scenario", () => {
  it("issue archive hides comments", async () => {
    const t = await createTenant("s1", "enterprise");
    const i = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "AlphaIssue" }));
    await comment(t, i.id, "AlphaComment");
    expect(await hits(t, "Alpha")).toBe(2);
    await issueService.archiveIssue(t.actors.member, t.org.id, i.id);
    expect(await hits(t, "Alpha")).toBe(0);
  });

  for (const archiveIssues of [false, true]) {
    it("project archive/restore archiveIssues=" + archiveIssues, async () => {
      const t = await createTenant("s2" + archiveIssues, "enterprise");
      const p = await projectService.createProject(t.actors.admin, { orgId: t.org.id, name: "BetaProj", slug: "beta", key: "BET", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null } as any);
      const kept = await issueService.createIssue(t.actors.member, issueInput(t.org.id, p.id, { title: "BetaKept" }));
      const pre = await issueService.createIssue(t.actors.member, issueInput(t.org.id, p.id, { title: "BetaPreArchived" }));
      await comment(t, kept.id, "BetaCommentKept");
      await comment(t, pre.id, "BetaCommentPre");
      const c3 = await comment(t, kept.id, "BetaDeleted");
      await commentService.deleteComment(t.actors.member, { orgId: t.org.id, commentId: c3.id } as any);
      await issueService.archiveIssue(t.actors.member, t.org.id, pre.id);
      expect(await hits(t, "Beta")).toBe(3);
      await projectService.archiveProject(t.actors.admin, { orgId: t.org.id, projectId: p.id, archiveIssues });
      expect(await hits(t, "Beta")).toBe(0);
      if (!archiveIssues) {
        await comment(t, kept.id, "BetaLateComment");
        await issueService.updateIssue(t.actors.member, { orgId: t.org.id, issueId: kept.id, title: "BetaEdited" } as any);
        expect(await hits(t, "Beta")).toBe(0);
        expect(await searchRepo.countIndexed(t.org.id)).toBe(0);
      }
      await projectService.restoreProject(t.actors.admin, t.org.id, p.id);
      if (!archiveIssues) {
        expect(await hits(t, "Beta")).toBe(4);
        expect(await hits(t, "BetaEdited")).toBe(1);
        expect(await hits(t, "BetaKept")).toBe(0);
      } else {
        expect(await hits(t, "Beta")).toBe(1);
      }
      const before = await searchRepo.countIndexed(t.org.id);
      await runSearchReindexJob(t.org.id);
      expect(await searchRepo.countIndexed(t.org.id)).toBe(before + 1); // tenant fixture project
    });
  }

  it("rebuild is exact, paged and tenant-scoped", async () => {
    const t = await createTenant("s3", "enterprise");
    const other = await createTenant("s3other", "enterprise");
    await issueService.createIssue(other.actors.member, issueInput(other.org.id, other.project.id, { title: "GammaOther" }));
    const otherCount = await searchRepo.countIndexed(other.org.id);
    let expected = 1;
    for (let n = 0; n < 230; n++) {
      const i = await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title: "Gamma" + n }) as any, t.userIds.member, n + 1);
      expected++;
      if (n % 50 === 0) {
        for (let k = 0; k < 120; k++) await commentRepo.insertComment({ orgId: t.org.id, issueId: i.id, body: "GammaC" + k, parentId: null, mentionedUserIds: [] } as any, t.userIds.member);
        expected += 120;
      }
      if (n === 7) { await issueRepo.archiveIssue(t.org.id, i.id); await searchRepo.upsertSearchDocument(t.org.id, "issue", i.id, "Gamma stale", t.project.id); expected--; }
    }
    await searchRepo.upsertSearchDocument(t.org.id, "comment", "nonexistent", "Gamma ghost", null);
    const r = await runSearchReindexJob(t.org.id);
    expect(r.failed).toBe(0);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(expected);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(otherCount);
    expect(await hits(t, "Gamma")).toBe(expected - 1);
    await runSearchReindexJob(t.org.id);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(expected);
  });
});
EOF
